  12: // HTTP、CLI 与 MCP 使用同一个 Store，页面只保存尚未提交的编辑缓冲。
  13: export function prototypeServer(store:Store,defaultWorkId:string){
  14:   return createServer(async(request,response)=>{
  15:     try{
  16:       const url=new URL(request.url??'/', 'http://127.0.0.1');
  17:       if(request.method==='GET'&&url.pathname==='/api/config'){json(response,200,{workId:defaultWorkId});return;}
  18:       if(request.method==='GET'&&url.pathname==='/api/work'){
  19:         const id=workId.parse(url.searchParams.get('work'));const work=store.getWork(id);
  20:         const summary=store.exportWork(id);const chapters=store.listChapters(id).map(c=>({...store.getChapter(id,c.number)!,basisCurrent:summary.chapters.find(s=>s.number===c.number)!.basisCurrent}));
  21:         json(response,200,{work,chapters});return;
  22:       }
  23:       if(request.method==='POST'&&url.pathname==='/api/draft'){
  24:         const submitted=draftInput.parse(await input(request));const saved=store.saveDraft(submitted,'human');json(response,200,saved);return;
  25:       }
  26:       const asset=assets.get(url.pathname);
  27:       if(request.method==='GET'&&asset){const bytes=await readFile(new URL('../prototype/'+asset,import.meta.url));response.writeHead(200,{'content-type':mime.get(asset)+'; charset=utf-8','cache-control':'no-store'});response.end(bytes);return;}
